// Desktop OS – Deel II: Windows – Werkcollege 2
// v = vraag, a = antwoord, o = onderwerp, uitleg = extra uitleg, img/imgAntwoord = afbeelding (map afbeeldingen/)
// wit: true = witte kaart die de cursus voorstelt · extra: true = extra info, niet uit de cursus (turquoise rand)
// oefening: true = blauwe oefenkaart: typ het commando. In a staan commando's na "$ "; regels die met 2 spaties beginnen zijn toetsen of uitvoer.
// De structuur onderaan bepaalt het overzicht rechts.

const kaarten_DOS_windows_wc2 = [
  // ===== PC-naam =====
  { v: "PC-naam", a: "• De PC-naam is belangrijk: zo herken je de pc's in je netwerk, en zo identificeert de domain controller jouw pc.\n• Namen moeten uniek zijn, anders krijg je overlappingen en problemen op je domein.\n• Bij elke Windows-installatie kies je een PC-naam; je kan hem op verschillende manieren veranderen.\n• Rechtsklik op de startknop: een overzicht van veel gebruikte tools.\n• Wijzigen: System Settings → System → About → Rename this PC.", o: "PC-naam", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_rename_pc.jpg" },
  { v: "Waarom is de PC-naam belangrijk?", a: "Zo herken je makkelijk de pc's in je netwerk, en zo identificeert je domain controller jouw pc.", o: "PC-naam" },
  { v: "Waarom moeten PC-namen uniek zijn?", a: "Om overlappingen en problemen op je domein te vermijden.", o: "PC-naam" },
  { v: "Wat opent een rechtsklik op de startknop?", a: "Een overzicht van verschillende tools en opties die je vaak nodig hebt in Windows.", o: "PC-naam" },
  { v: "Verander de naam van je VM naar <voornaam>-<verkorte familienaam>-VM.", a: "Rechtsklik op de startknop → System → About → Rename this PC", o: "PC-naam", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_rename_pc.jpg",
    uitleg: "Daarna herstart je de pc." },
  // ===== Werkgroep en domein =====
  { v: "Werkgroep en domein", a: "• Werkgroep: een verzameling pc's binnen een netwerk. Ze kunnen bronnen delen (printers, scanners, folders, bestanden); de werkgroep toont dat duidelijker, maar biedt verder geen meerwaarde. Geen controle: iedereen kan erin.\n• Domein: ook een verzameling computers, maar beheerd door een Domain Controller. Je draagt de controle over: internetregels, wallpaper, software installeren, pc-instellingen en accounts.\n• Een domein is beveiligd: folders, bestanden en andere resources worden veilig gedeeld.", o: "Werkgroep en domein", wit: true },
  { v: "Wat is een werkgroep?", a: "Een verzameling pc's binnen een bepaald netwerk, die bronnen kunnen delen (printers, scanners, folders, bestanden).", o: "Werkgroep en domein" },
  { v: "Welke meerwaarde en welke controle biedt een werkgroep?", a: "Ze toont de gedeelde bronnen duidelijker, maar biedt verder geen meerwaarde. Er is geen enkele controle: iedereen kan in een werkgroep komen.", o: "Werkgroep en domein" },
  { v: "Wat is een domein?", a: "Een verzameling computers die beheerd worden door een Domain Controller.", o: "Werkgroep en domein" },
  { v: "Wat betekent het als je pc deel uitmaakt van een domein? Geef voorbeelden.", a: "Je draagt de controle over aan de Domain Controller: bv. internetregels, de wallpaper, software installeren, pc-instellingen en accounts wijzigen.", o: "Werkgroep en domein" },
  { v: "Wat is het grote verschil tussen een werkgroep en een domein?", a: "Een domein is beveiligd en deelt folders, bestanden en resources op een beveiligde manier; een werkgroep heeft geen controle.", o: "Werkgroep en domein" },
  // ===== DNS =====
  { v: "DNS", a: "• DNS = Domain Name System: vertaalt domeinnamen (zoals google.com) naar IP-adressen (zoals 142.250.74.14).\n• Computers werken met IP-adressen, mensen onthouden makkelijker namen.\n• Opdracht: surf naar http://desktoposisawesome.be (bestaat niet), verander je DNS en surf opnieuw: nu werkt het.\n• De DNS-server van de opdracht is enkel zichtbaar binnen het schoolnetwerk: verbind via VPN.\n• Wijzigen: rechtsklik startknop → Network Connections → Ethernet → DNS server assignment → manueel, voor IPv4.\n• In hetzelfde venster pas je ook het IP-adres, het subnet mask en de default gateway aan.", o: "DNS", wit: true,
    uitleg: "Het adres van de DNS-server van de school staat in de cursus; ik zet het bewust niet op de kaart." },
  { v: "Waarvoor staat DNS, en wat doet het?", a: "Domain Name System: het vertaalt domeinnamen (zoals google.com) naar IP-adressen (zoals 142.250.74.14).", o: "DNS" },
  { v: "Waarom bestaat DNS?", a: "Computers werken met IP-adressen, maar mensen onthouden makkelijker namen. Zo bezoek je een website door een naam te typen.", o: "DNS" },
  { v: "Waarom moet je voor de DNS-opdracht met VPN verbonden zijn?", a: "De DNS-server is enkel zichtbaar binnen het schoolnetwerk.", o: "DNS" },
  { v: "Wat kan je nog aanpassen in hetzelfde venster als de DNS-server?", a: "Het IP-adres, het subnet mask en de default gateway.", o: "DNS" },
  { v: "Stel de DNS-server van je Ethernet-adapter manueel in voor IPv4.", a: "Rechtsklik op de startknop → Network Connections → Ethernet → DNS server assignment → Edit → Manual → IPv4", o: "DNS", oefening: true,
    uitleg: "Vul de Preferred en Alternate DNS-server uit de cursus in." },
  { v: "Controleer in de CLI op welk IP-adres desktoposisawesome.be gehost wordt.", a: "C:\\> ping desktoposisawesome.be", o: "DNS", oefening: true,
    uitleg: "ping = stuur een testbericht naar een computer. In de uitvoer zie je het IP-adres waarop de naam uitkomt (via DNS).\nVoor het wijzigen van je DNS bestaat de site niet; daarna wel." },
  // ===== Task Manager: Processes =====
  { v: "Task Manager", a: "• Openen met Ctrl+Shift+Esc (zie werkcollege 1).\n• Om te zien waarom je pc traag is, of om meer in detail te kijken. Ook leken kunnen er basistaken mee doen.\n• Tabbladen: Processes, Performance, Startup apps, Users, Details en Services.", o: "Task Manager: Processes", wit: true },
  { v: "Task Manager: Processes", a: "• Een lijst van alle draaiende processen, normaal in 3 delen: Apps, Background processes en Windows Processes (op de VM anders).\n• In één oogopslag de load op CPU, geheugen, schijf en netwerk.\n• Onbekend of verdacht proces (mogelijk virus)? Rechtsklik → Search online.\n• Je kan ook een dump file van een proces maken.", o: "Task Manager: Processes", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_taakbeheer_processes.jpg" },
  { v: "Open de Task Manager.", a: "  Ctrl+Shift+Esc", o: "Task Manager: Processes", oefening: true },
  { v: "Welke tabbladen heeft de Task Manager?", a: "Processes, Performance, Startup apps, Users, Details en Services.", o: "Task Manager: Processes" },
  { v: "In welke 3 delen is Processes normaal verdeeld?", a: "Apps, Background processes en Windows Processes.", o: "Task Manager: Processes" },
  { v: "Wat zie je in één oogopslag in Processes?", a: "De load die elk proces plaatst op de CPU, het geheugen, de schijf en het netwerk.", o: "Task Manager: Processes" },
  { v: "Wat doe je met een proces dat je niet kent of niet vertrouwt?", a: "Rechtsklik → Search online, om op te zoeken wat het doet.", o: "Task Manager: Processes" },
  { v: "Wat kan je nog maken van een proces in Processes?", a: "Een dump file.", o: "Task Manager: Processes" },
  // ===== Task Manager: Performance =====
  { v: "Task Manager: Performance (CPU)", a: "• Diagrammen die het systeem voorstellen, met nuttige info.\n• CPU: het huidige processorgebruik. Bijna 100% = processor-intensieve programma's (bv. ingewikkelde berekeningen).\n• Reageert je pc niet meer goed? Kijk of de processor een tijdsintensieve taak uitvoert.\n• Gecrashte programma's kunnen de processor bijna 100% bezighouden zonder iets te doen. Het verbruik per programma zie je in Processes; zo'n proces sluit je best af.\n\nOpdracht: vul de kloksnelheid, het aantal processen en het aantal threads in.", o: "Task Manager: Performance", wit: true },
  { v: "Task Manager: Performance (Memory)", a: "• Memory: hoeveel RAM-geheugen er gebruikt wordt.\n• Benadert Available 0 MB, dan wordt de pc merkbaar trager: Windows schrijft delen van het RAM naar de harde schijf. Dat heet virtueel geheugen (virtual memory).\n• Committed: hoeveel virtueel geheugen er gebruikt wordt. Vaak geen geheugen over? Installeer extra RAM.\n• Het virtuele geheugen staat in pagefile.sys, meestal op C:\\ (verborgen systeembestand).\n• Cached Memory: hoeveel geheugen de systeemprocessen gebruiken.\n• Paged Pool: het virtuele geheugen dat de kernel gebruikt; Non-paged Pool: het effectieve geheugen dat de kernel nu gebruikt.", o: "Task Manager: Performance", wit: true },
  { v: "Task Manager: Performance (Disk, Ethernet, Resource Monitor)", a: "• Disk: de activiteit van je logische schijven. Bij het kopiëren van een groot bestand gaan de waarden omhoog; duurt het te lang, kijk naar de snelheid.\n• Ethernet: het IP-adres van elke adapter en het binnenkomende en uitgaande verkeer. Via RDP is Sent nooit 0; Received gaat omhoog als je de muis beweegt (de cursorpositie wordt doorgestuurd). Meer: rechtsklik → View network details.\n• Resource Monitor (via de 3 puntjes rechtsboven): nog meer detail per proces, bv. het netwerkverkeer en met welk extern IP-adres het verbonden is; telt vanaf het moment dat je kijkt.\n\nOpdracht: open programma's tot je over het fysieke geheugen (Total) gaat: de pc schrijft nu processen naar de schijf (pages).", o: "Task Manager: Performance", wit: true },
  { v: "Good to know: Performance (niet te kennen)", a: "• Verklaar waarom de schijfactiviteit stijgt wanneer het geheugen dreigt vol te zitten.\n• Gebruik Run (Win+R) met dxdiag en bekijk de grootte van de pagefile.\n• App History: de gebruikte resources van elke Windows Store App, om te zien welke app je pc trager maakt.", o: "Task Manager: Performance", extra: true, nietTeKennen: true,
    uitleg: "Good to know: niet te kennen leerstof." },
  { v: "Wat toont CPU in Performance, en wat betekent bijna 100%?", a: "Het huidige processorgebruik. Bijna 100% = er draaien processor-intensieve programma's (bv. ingewikkelde berekeningen).", o: "Task Manager: Performance" },
  { v: "Wat kan een gecrasht programma doen met de CPU, en wat doe je dan?", a: "Het kan de processor bijna 100% bezighouden zonder iets te doen. Bekijk het in Processes en sluit het af.", o: "Task Manager: Performance" },
  { v: "Zoek de kloksnelheid, het aantal processen en het aantal threads.", a: "Task Manager (Ctrl+Shift+Esc) → Performance → CPU", o: "Task Manager: Performance", oefening: true,
    uitleg: "Onderaan bij de CPU staan Speed, Processes en Threads." },
  { v: "Wat gebeurt er als Available bij Memory 0 MB benadert?", a: "De pc wordt merkbaar trager: Windows schrijft delen van het RAM naar de harde schijf (virtueel geheugen).", o: "Task Manager: Performance" },
  { v: "Wat is virtueel geheugen, en in welk bestand staat het?", a: "Geheugen op de harde schijf dat dient als tijdelijke opslag voor wat niet in het RAM past. Het staat in pagefile.sys, meestal op C:\\ (verborgen).", o: "Task Manager: Performance" },
  { v: "Wat toont Committed, en wat doe je als een pc vaak geen geheugen over heeft?", a: "Hoeveel virtueel geheugen er gebruikt wordt. Installeer dan best extra RAM.", o: "Task Manager: Performance" },
  { v: "Wat zijn Cached Memory, Paged Pool en Non-paged Pool?", a: "Cached: het geheugen dat de systeemprocessen gebruiken.\nPaged Pool: het virtuele geheugen van de kernel.\nNon-paged Pool: het effectieve geheugen dat de kernel nu gebruikt.", o: "Task Manager: Performance" },
  { v: "Wat toont Disk in Performance?", a: "De activiteit van je logische schijven, bv. tijdens het kopiëren van een groot bestand. De snelheid geeft een eerste aanwijzing of er iets mis is.", o: "Task Manager: Performance" },
  { v: "Waarom is Sent bij Ethernet nooit 0, en wanneer stijgt Received?", a: "Via Remote Desktop wordt altijd beeld verstuurd. Received stijgt als je de muis beweegt: de cursorpositie wordt doorgestuurd.", o: "Task Manager: Performance" },
  { v: "Wat kan de Resource Monitor meer, en hoe open je hem?", a: "Via de 3 puntjes rechtsboven. Meer detail per proces, bv. het netwerkverkeer en met welk extern IP-adres het verbonden is, gemeten vanaf het moment dat je kijkt.", o: "Task Manager: Performance" },
  { v: "Open programma's tot je over het fysieke geheugen gaat, en bekijk wat er gebeurt.", a: "Task Manager → Performance → Memory: volg In use tegenover Total", o: "Task Manager: Performance", oefening: true,
    uitleg: "Daarna schrijft de pc regelmatig processen naar de schijf (pages): de schijfactiviteit stijgt." },
  { v: "Bekijk de grootte van de pagefile met dxdiag.", a: "  Win+R\n  dxdiag", o: "Task Manager: Performance", extra: true, nietTeKennen: true,
    uitleg: "Win+R = open Run.\ndxdiag = start de DirectX-diagnose, waarin je o.a. de grootte van de pagefile ziet.\nGood to know: niet te kennen leerstof." },
  // ===== Task Manager: Startup apps, Users, Details en Services =====
  { v: "Startup apps en Users", a: "• Startup apps: taken die automatisch starten bij het opstarten. Uitzetten is makkelijk geworden; je ziet ook hoeveel vertraging ze veroorzaken.\n• Users: per gebruiker hoeveel processorkracht, geheugen, schijf en netwerk hij gebruikt. Bv. een gebruiker die vergrendelt i.p.v. af te melden, laat processen draaien. Met genoeg rechten: rechtsklik → Sign Off.\n\nOpdracht: maak een lokaal useraccount, laat een medestudent via RDP op je VM verbinden: beide sessies staan onder Users.", o: "Task Manager: Startup apps, Users, Details en Services", wit: true },
  { v: "Details en Services", a: "• Details: info per proces; je kan o.a. de prioriteit wijzigen.\n• Windows is priority based: een proces met een hogere prioriteit komt vaker en langer aan de beurt.\n• Services: services opstarten, afsluiten of herstarten. Meer? Rechtsklik → Open Services.", o: "Task Manager: Startup apps, Users, Details en Services", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_details_prioriteit.jpg",
    uitleg: "Good to know: elk proces heeft, zoals in Linux, een Process ID (PID). In CMD toon je de processen met tasklist en sluit je ze af met taskkill." },
  { v: "Wat zijn Startup apps, en wat toont de Task Manager erover?", a: "Taken die automatisch starten bij het opstarten van het OS. Je kan ze makkelijk uitzetten en ziet hoeveel vertraging ze veroorzaken.", o: "Task Manager: Startup apps, Users, Details en Services" },
  { v: "Wat zie je in het tabblad Users, en wat kan je er doen?", a: "Per gebruiker de processorkracht, het geheugen, de schijf en het netwerk die hij gebruikt. Met genoeg rechten kan je een gebruiker afmelden: rechtsklik → Sign Off.", o: "Task Manager: Startup apps, Users, Details en Services" },
  { v: "Waarom kan een vergrendelde sessie van een andere gebruiker je pc traag maken?", a: "Hij laat op de achtergrond allerlei processen draaien, in plaats van zich af te melden.", o: "Task Manager: Startup apps, Users, Details en Services" },
  { v: "Wat kan je in het tabblad Details wijzigen?", a: "Onder andere de prioriteit van een proces.", o: "Task Manager: Startup apps, Users, Details en Services" },
  { v: "Wat betekent: Windows is priority based?", a: "Een proces met een hogere prioriteit komt vaker en langer aan de beurt dan een proces met een lagere prioriteit.", o: "Task Manager: Startup apps, Users, Details en Services" },
  { v: "Welke prioriteiten kan je een proces geven?", a: "Realtime, High, Above normal, Normal, Below normal en Low.", o: "Task Manager: Startup apps, Users, Details en Services", imgAntwoord: "afbeeldingen/DesktopOS_windows_wc2/w2_details_prioriteit.jpg" },
  { v: "Wat kan je in het tabblad Services, en hoe ga je verder?", a: "Services opstarten, afsluiten of herstarten. Meer: rechtsklik → Open Services.", o: "Task Manager: Startup apps, Users, Details en Services" },
  { v: "Toon de processen in CMD en beëindig een onbelangrijk proces.", a: "C:\\> tasklist\nC:\\> taskkill /PID 1234", o: "Task Manager: Startup apps, Users, Details en Services", extra: true, nietTeKennen: true,
    uitleg: "tasklist = toon alle draaiende processen, met hun PID (procesnummer).\ntaskkill /PID 1234 = beëindig het proces met dat PID; vervang 1234 door het PID uit tasklist. Ook kan: taskkill /IM notepad.exe (op naam).\nGood to know: niet te kennen leerstof." },
  // ===== Device Manager =====
  { v: "Device Manager", a: "• Openen: rechtsklik op de startknop → Device Manager.\n• Alle hardware: harde schijven, dvd, keyboard, muis, netwerkadapter, geluidskaart, ... en ook chipsets op het moederbord.\n• Bij problemen met een apparaat kijk je hier eerst. Een softwarefout los je vaak op door de driver te herinstalleren: rechtsklik → Update Driver Software (enkel als administrator).\n• Unknown device: Properties → Details → hardware id. Zo weet je welke hardware het is en welke driver je zoekt.\n• View aanpassen: i.p.v. by type ook by connection.\n\nOpdracht: controleer als admin of de Display Adapter de laatste driver heeft.", o: "Device Manager", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_device_manager.jpg",
    uitleg: "Good to know: ook te openen via Run (Win+R) met devmgmt.msc, zoals de meeste tools. Of met msinfo32 (bv. de IRQ-kanalen)." },
  { v: "Open de Device Manager.", a: "Rechtsklik op de startknop → Device Manager", o: "Device Manager", oefening: true },
  { v: "Open de Device Manager via Run.", a: "  Win+R\n  devmgmt.msc", o: "Device Manager", extra: true, nietTeKennen: true,
    uitleg: "Win+R = open Run.\ndevmgmt.msc = de Device Manager.\nGood to know: niet te kennen leerstof." },
  { v: "Wat kan je in de Device Manager bekijken?", a: "Alle hardware: harde schijven, dvd, keyboard, muis, netwerkadapter, geluidskaart, ... en ook chipsets op het moederbord.", o: "Device Manager" },
  { v: "Hoe los je een probleem met een apparaat op als het om een softwarefout gaat?", a: "De driver herinstalleren: rechtsklik op het apparaat → Update Driver Software (enkel als administrator).", o: "Device Manager" },
  { v: "Hoe kom je te weten welke hardware een unknown device is?", a: "Properties → Details → het hardware id. Zo weet je ook welke drivers je moet zoeken.", o: "Device Manager" },
  { v: "Hoe kan je de View van de Device Manager aanpassen?", a: "In plaats van by type, by connection tonen.", o: "Device Manager" },
  { v: "Controleer als admin of de Display Adapter de laatste driver heeft.", a: "Device Manager → Display adapters → rechtsklik → Update Driver Software", o: "Device Manager", oefening: true },
  { v: "Bekijk de IRQ-kanalen met msinfo32.", a: "  Win+R\n  msinfo32", o: "Device Manager", extra: true, nietTeKennen: true,
    uitleg: "Win+R = open Run.\nmsinfo32 = System Information, met o.a. de IRQ-kanalen.\nGood to know: niet te kennen leerstof." },
  // ===== Microsoft Management Console =====
  { v: "Good to know: Microsoft Management Console (MMC)", a: "• Een raamwerk waarin je plug-ins (snap-ins) laadt om zaken van je computer te configureren.\n• Openen: Start → mmc.exe typen in het zoekveld (de naam moet juist zijn).\n• Plug-ins laden: File → Add/remove Snap-in, bv. Device Manager en Services; kies Local, of een ander toestel (Remote Management).\n• Voor veel zaken heb je adminrechten nodig, maar je kan ook veel info lezen.", o: "Microsoft Management Console", extra: true, nietTeKennen: true,
    uitleg: "Good to know: niet te kennen leerstof." },
  { v: "Open de Microsoft Management Console en laad de snap-ins Device Manager en Services.", a: "Start → mmc.exe\nFile → Add/remove Snap-in → Device Manager en Services → Local", o: "Microsoft Management Console", extra: true, nietTeKennen: true,
    uitleg: "mmc.exe = de Microsoft Management Console: één venster waarin je beheertools (snap-ins) samenzet.\nAdd/remove Snap-in = kies welke tools erin komen.\nGood to know: niet te kennen leerstof." },
  // ===== Disk Management =====
  { v: "Disk Management", a: "• De harde schijf wordt via volumes ter beschikking gesteld.\n• In de Disk Management Tool bekijk en wijzig je de opdeling in partities.\n• In de Verkenner zie je geen partities, wel de inhoud van de volumes.\n• Een volume (bv. C:\\ of D:\\) is een letter gekoppeld aan een partitie, optische drive of extern opslagmedium.\n• C:\\ is meestal de systeemschijf met de belangrijke systeembestanden.", o: "Disk Management", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_disk_management.jpg" },
  { v: "Disk Management: tabbladen General en Tools", a: "Rechtsklik op een schijf → Properties.\n• General: gebruikte en vrije ruimte; bestanden comprimeren om plaats te besparen; een index opbouwen om sneller te zoeken.\n• Tools: de schijf nakijken op fouten (bv. defecte sectoren) en defragmenteren: verspreide (stukken van) bestanden weer samen plaatsen, zodat ze sneller te openen zijn.", o: "Disk Management", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_c_tools.jpg",
    uitleg: "Good to know: zoek op of het slim is om een SSD te defragmenteren. Tabbladen Security (toegangsrechten), Quota (maximale opslag per gebruiker, bv. Rita 200 MB, John 100 MB) en Sharing (delen op het netwerk, enkel admin)." },
  { v: "Hoe stelt Windows de harde schijf ter beschikking aan gebruikers?", a: "Aan de hand van volumes.", o: "Disk Management" },
  { v: "Wat doe je met de Disk Management Tool?", a: "De opdeling van je harde schijf in partities bekijken en wijzigen.", o: "Disk Management" },
  { v: "Wat is een volume?", a: "Een letter (bv. C:\\ of D:\\) die gekoppeld wordt aan een partitie, een optische drive of een extern opslagmedium.", o: "Disk Management" },
  { v: "Wat zie je in de Verkenner wel en niet van je schijven?", a: "Niet de fysieke opdeling in partities, wel de inhoud van de volumes.", o: "Disk Management" },
  { v: "Wat is de C:\\-schijf meestal?", a: "De systeemschijf, met de belangrijke systeembestanden van het besturingssysteem.", o: "Disk Management" },
  { v: "Wat bevat het tabblad General van een schijf?", a: "De gebruikte en vrije ruimte; de mogelijkheid om te comprimeren; een index om sneller te zoeken.", o: "Disk Management", img: "afbeeldingen/DesktopOS_windows_wc2/w2_c_general.jpg" },
  { v: "Wat bevat het tabblad Tools van een schijf?", a: "Nakijken op fouten (bv. defecte sectoren) en defragmenteren.", o: "Disk Management", img: "afbeeldingen/DesktopOS_windows_wc2/w2_c_tools.jpg" },
  { v: "Wat is defragmenteren, en waarom helpt het?", a: "Verspreide bestanden (of blokken ervan) weer samen plaatsen. Het grootste tijdsverlies bij het openen zit in verspreide bestanden, dus de pc kan sneller werken.", o: "Disk Management" },
  { v: "Open de eigenschappen van de C:\\-schijf.", a: "Verkenner → rechtsklik op C:\\ → Properties", o: "Disk Management", oefening: true },
  { v: "Een SSD defragmenteren?", a: "Op een SSD heeft defragmenteren geen zin: elk blok is even snel bereikbaar, en onnodig schrijven verkort de levensduur. Windows doet bij een SSD in de plaats een 'optimize' (TRIM).", o: "Disk Management", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus." },
  // ===== NTFS, FAT en exFAT =====
  { v: "NTFS, FAT en exFAT", a: "• Sinds Windows NT twee formatteringstypes: NTFS (New Technology File System) en FAT (File Allocation Table).\n• FAT: geen beveiliging (iedereen opent alles), bestanden max. 4 GB. Voordeel: Linux en macOS werken er zonder problemen mee.\n• exFAT (2006): lost de grootte-beperking op; meer ondersteund dan NTFS, maar sommige oudere systemen hebben er problemen mee. Windows 11 biedt geen exFAT-optie bij formatteren: gebruik externe tools of de CLI.\n• NTFS: beveiliging op bestandsniveau, compressie, encryptie, ... Gebruikt op alle huidige Windows-computers.\n• Op NTFS heeft elk bestand en elke map een owner (de maker) en een lijst met rechten voor gebruikers en groepen. Enkel de administrator kan de owner wijzigen.", o: "NTFS, FAT en exFAT", wit: true,
    uitleg: "Good to know: er bestaat een format-commando, maar via diskpart gaat het sneller." },
  { v: "Opdracht: partitie maken en formatteren", a: "• Zoek op: wat formatteren betekent, low-level vs. high-level formatting, zero bit fill, Quick Format vs. Full Format.\n• Maak een nieuwe partitie door C:\\ met 5 GB te verkleinen (Shrink Volume).\n• Geef ze de letter E: en formatteer met FAT. Navigeer in de CLI naar de nieuwe schijf.\n• Formatteer opnieuw, nu met exFAT.", o: "NTFS, FAT en exFAT", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_shrink_volume.jpg" },
  { v: "Welke 2 formatteringstypes ondersteunt Windows sinds Windows NT? Voluit?", a: "NTFS (New Technology File System) en FAT (File Allocation Table).", o: "NTFS, FAT en exFAT" },
  { v: "Wat zijn de nadelen van FAT, en wat is het enige voordeel?", a: "Geen beveiliging (iedereen kan alle bestanden openen) en bestanden van max. 4 GB. Voordeel: Linux en macOS werken er zonder problemen mee.", o: "NTFS, FAT en exFAT" },
  { v: "Waarom kwam exFAT, en wanneer?", a: "In 2006, om de bestandsgroottebeperking van FAT op te lossen.", o: "NTFS, FAT en exFAT" },
  { v: "Wat is het probleem met exFAT?", a: "Sommige oudere systemen en distro's hebben er problemen mee. En Windows 11 biedt geen exFAT-optie bij formatteren (externe tools of de CLI).", o: "NTFS, FAT en exFAT" },
  { v: "Wat biedt NTFS meer dan FAT?", a: "Beveiliging op bestandsniveau, comprimeren, encryptie, ... Daarom gebruiken alle huidige Windows-computers NTFS.", o: "NTFS, FAT en exFAT" },
  { v: "Wie is de owner van een bestand op NTFS, en wie kan hem wijzigen?", a: "Typisch de gebruiker die het bestand gemaakt heeft. Enkel de administrator kan de owner wijzigen.", o: "NTFS, FAT en exFAT" },
  { v: "Wat bevat elk bestand en elke map op NTFS nog?", a: "Een lijst van gebruikers en groepen met rechten.", o: "NTFS, FAT en exFAT" },
  { v: "Maak een nieuwe partitie door de C:\\-schijf met 5 GB te verkleinen.", a: "Disk Management → rechtsklik op C: → Shrink Volume → 5120 MB\nRechtsklik op de vrije ruimte → New Simple Volume", o: "NTFS, FAT en exFAT", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_shrink_volume.jpg" },
  { v: "Navigeer in de CLI naar je nieuwe schijf E: en toon de inhoud.", a: "C:\\> E:\nE:\\> dir", o: "NTFS, FAT en exFAT", oefening: true,
    uitleg: "E: = ga naar het volume E (de prompt wordt E:\\>).\ndir = toon de inhoud." },
  { v: "Formatteer partitie E: opnieuw met exFAT, via diskpart.", a: "C:\\> diskpart\nDISKPART> list disk\nDISKPART> select disk 0\nDISKPART> list partition\nDISKPART> select partition 3\nDISKPART> format fs=exfat", o: "NTFS, FAT en exFAT", oefening: true, imgAntwoord: "afbeeldingen/DesktopOS_windows_wc2/w2_diskpart.jpg",
    uitleg: "diskpart = de tool om schijven en partities te beheren (prompt DISKPART>).\nlist disk / select disk 0 = toon de schijven en kies schijf 0.\nlist partition / select partition 3 = toon de partities en kies je nieuwe partitie (kies je eigen nummer).\nformat fs=exfat = formatteer met het bestandssysteem exFAT.\nEr bestaat ook een format-commando, maar diskpart gaat sneller." },
  { v: "Formatteren, low-level en high-level", a: "Formatteren = een schijf of partitie klaarmaken voor gebruik met een bestandssysteem (NTFS, FAT, ...); de bestaande gegevens worden onbruikbaar.\nLow-level formatting: de fysieke indeling van de schijf in sporen en sectoren (gebeurt in de fabriek).\nHigh-level formatting: het bestandssysteem aanmaken (wat Windows doet).", o: "NTFS, FAT en exFAT", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus." },
  { v: "Zero fill, Quick Format en Full Format", a: "Zero (bit) fill: elke sector van de schijf wordt met nullen overschreven, zodat oude data niet meer te herstellen is.\nQuick Format: maakt enkel een nieuw, leeg bestandssysteem; snel.\nFull Format: controleert ook de hele schijf op slechte sectoren (en schrijft sinds Vista nullen); traag.", o: "NTFS, FAT en exFAT", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus." },
  // ===== Programma's en features =====
  { v: "Programma's en features", a: "• De bovenste optie in het rechtsklikmenu van de startknop: apps verwijderen (Installed apps).\n• Settings → Apps: Advanced app settings, bv. Windows Updates de-installeren (als een update problemen geeft, tot er een bugfix is).\n• System → Optional Features: features aan- en uitzetten; via Related settings → More Windows features.\n• Een feature die je in je 2de jaar nodig hebt: IIS (Internet Information Services).\n\nOpdrachten: installeer en de-installeer een tool uit werkcollege 1; zet IIS aan.", o: "Programma's en features", wit: true },
  { v: "Waar verwijder je snel apps?", a: "Via de bovenste optie in het rechtsklikmenu van de startknop (Installed apps).", o: "Programma's en features" },
  { v: "Waarom zou je een Windows Update de-installeren, en waar?", a: "Als een update bij bepaalde gebruikers problemen geeft, tot er een bugfix komt. Via Settings → Apps → Advanced app settings.", o: "Programma's en features" },
  { v: "Waar zet je Windows-features aan en uit?", a: "System → Optional Features; extra via Related settings → More Windows features.", o: "Programma's en features" },
  { v: "Welke feature heb je waarschijnlijk in je 2de jaar nodig?", a: "IIS (Internet Information Services).", o: "Programma's en features" },
  { v: "Zet Internet Information Services aan.", a: "Settings → System → Optional Features → More Windows features → vink Internet Information Services aan", o: "Programma's en features", oefening: true },
  { v: "Installeer een tool uit werkcollege 1 en de-installeer ze weer.", a: "C:\\> winget install pakket\nC:\\> winget uninstall pakket", o: "Programma's en features", oefening: true,
    uitleg: "winget install pakket = installeer de tool.\nwinget uninstall pakket = verwijder ze weer.\nOf via Installed apps (rechtsklik op de startknop)." },
  // ===== UAC =====
  { v: "UAC (User Account Control)", a: "• 'Least user' of 'standard user accounts': werken als gewone gebruiker, niet altijd als administrator.\n• Sinds Windows Vista: UAC, om least user te benutten en minder kansen te geven aan spyware en verdachte software.\n• Iedereen, ook een admin, werkt als gewone gebruiker. Pas bij een taak met adminrechten vraagt Windows 'Administrator Credentials':\n– geen lid van administrators: gebruikersnaam + wachtwoord van een admin-account\n– wel lid: enkel toelating\n• Uitschakelen (geen goed idee): Change User Account Control settings op Never notify.\n\nOpdracht: wat is het grote nadeel om als admin al je programma's uit te voeren?", o: "UAC", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_uac.jpg" },
  { v: "Wat is het concept 'least user'?", a: "Je werkt als gewone gebruiker op je systeem en bent niet de hele tijd als administrator ingelogd.", o: "UAC" },
  { v: "Wat is het grote nadeel om als lid van de administrators groep al je programma's uit te voeren?", a: "Elk programma, ook spyware of verdachte software, krijgt dan meteen alle rechten en kan het systeem beschadigen.", o: "UAC" },
  { v: "Waarvoor staat UAC, sinds wanneer bestaat het en waarvoor werd het ontworpen?", a: "User Account Control, sinds Windows Vista. Om least user ten volle te benutten en minder kansen te geven aan spyware en verdachte software.", o: "UAC" },
  { v: "Hoe werkt iedereen onder UAC, ook een admin?", a: "Als gewone gebruiker. Pas bij een taak met adminrechten vraagt Windows Administrator Credentials.", o: "UAC" },
  { v: "Wat vraagt UAC aan een gebruiker die geen lid is van de administrators groep? En aan een lid?", a: "Geen lid: een gebruikersnaam en wachtwoord van een account in de administrators groep.\nWel lid: enkel een toelating om door te gaan.", o: "UAC" },
  { v: "Schakel UAC uit (geen goed idee).", a: "Change User Account Control settings → Never notify", o: "UAC", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_uac.jpg" },
  // ===== Users toevoegen =====
  { v: "Users toevoegen met lusrmgr", a: "• Kan op verschillende manieren, bv. ook via de Computer Management Tool.\n• Hier via lusrmgr: zoek lusrmgr.msc in de Windows Searchbar.\n• Je ziet alle gebruikers; een pijltje naar beneden = het account is disabled.\n• Onder Groups: groepen om policies (regels) op te leggen of extra opties en rechten te geven.\n\nOpdrachten: maak Jimmy, Joske en Jefke; disable Jimmy; Joske in Administrators; nieuwe groep Noobs met Jefke (location: de lokale pc, niet het domein).", o: "Users toevoegen", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_lusrmgr.jpg" },
  { v: "Open de tool om lokale gebruikers te beheren.", a: "Windows Searchbar → lusrmgr.msc", o: "Users toevoegen", oefening: true,
    uitleg: "lusrmgr.msc = Local Users and Groups: lokale gebruikers en groepen beheren." },
  { v: "Wat betekent een pijltje naar beneden bij een account in lusrmgr?", a: "Het account is disabled.", o: "Users toevoegen", img: "afbeeldingen/DesktopOS_windows_wc2/w2_lusrmgr.jpg" },
  { v: "Waarvoor dienen groepen in Windows?", a: "Om policies (regels) te verplichten, en om gebruikers extra opties en rechten op de pc te geven.", o: "Users toevoegen" },
  { v: "Maak de gebruikers Jimmy, Joske en Jefke, en disable Jimmy.", a: "lusrmgr.msc → Users → rechtsklik → New User (3 keer)\nRechtsklik Jimmy → Properties → Account is disabled", o: "Users toevoegen", oefening: true },
  { v: "Maak Joske lid van de Administrators groep.", a: "lusrmgr.msc → Groups → Administrators → Add → Joske", o: "Users toevoegen", oefening: true },
  { v: "Maak een groep Noobs met Jefke erin, met als location de lokale pc.", a: "lusrmgr.msc → Groups → rechtsklik → New Group → Noobs → Add → Locations: de lokale pc → Jefke", o: "Users toevoegen", oefening: true },
  // ===== User profiles =====
  { v: "User profiles", a: "• Elke gebruiker krijgt een Registry Hive en profielfolders, onder C:/Users.\n• Bekend: Documents, Downloads, Desktop.\n• Minder bekend: AppData (verborgen: vink hidden items aan). Applicaties bewaren er data en settings per gebruiker.\n• 3 subfolders, voor rechten en synchronisatie op het domein:\n– Local: enkel op deze pc, niet doorgegeven bij inloggen elders\n– LocalLow: minder rechten nodig om te schrijven (bv. protected mode van Internet Explorer)\n– Roaming: gesynchroniseerd via de Domain Controller, zodat je instellingen meegaan naar een andere pc in het domein\n• Snel naar AppData: typ %APPDATA% in de navigatiebalk van de Verkenner (een systeemvariabele).", o: "User profiles", wit: true },
  { v: "Wat krijgt elke gebruiker in Windows, en waar staan de profielfolders?", a: "Een Registry Hive en profielfolders, onder C:/Users.", o: "User profiles" },
  { v: "Wat is AppData, en waarom zie je het niet?", a: "Een verborgen map waarin applicaties data en settings per gebruiker bewaren. Vink hidden items aan.", o: "User profiles" },
  { v: "Welke 3 subfolders heeft AppData, en waarom die opsplitsing?", a: "Local, LocalLow en Roaming: voor rechten en synchronisatie op het domein.", o: "User profiles" },
  { v: "Wat is het verschil tussen Local, LocalLow en Roaming?", a: "Local: enkel op deze pc, niet doorgegeven.\nLocalLow: minder rechten nodig om te schrijven.\nRoaming: gesynchroniseerd via de Domain Controller, gaat mee naar een andere pc in het domein.", o: "User profiles" },
  { v: "Ga snel naar de AppData-map van je profiel in de Verkenner.", a: "Typ %APPDATA% in de navigatiebalk", o: "User profiles", oefening: true,
    uitleg: "%APPDATA% = een systeemvariabele: Windows vervangt ze door het pad naar de AppData-map van je profiel." },
  // ===== Het register =====
  { v: "Het register", a: "• Een centrale, hiërarchische database om het systeem te configureren voor gebruikers, toepassingen en apparaten.\n• Bevat o.a. profielen per gebruiker, geïnstalleerde toepassingen en welke documenten ze maken, instellingen van vensters en pictogrammen, de hardware en de poorten in gebruik.\n• Vervangt de tekst-configuratiebestanden van MS-DOS en Windows 3.x (Autoexec.bat, Config.sys).\n• Een registeronderdeel: een groep sleutels, subsleutels en waarden, met ondersteuningsbestanden (back-ups). De bestanden (behalve HKEY_CURRENT_USER) staan in c:/Windows/System32/config, of %SystemRoot%\\System32\\Config.\n• Bekijken met regedit. Waarden hebben een datatype, bv. DWORD (Double-Word).\n\nOpdracht: zoek op wat Registry hives zijn en kijk in HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\hivelist.", o: "Het register", wit: true },
  { v: "Het register: back-up en een tweak", a: "• Gebruikt om virussen volledig te verwijderen, of bij hardwareproblemen (bv. een cd-rom die niet herkend wordt). Opgelet: een verkeerde waarde kan het systeem serieus in de war sturen!\n• Maak eerst een back-up: kopieer de registerbestanden, of exporteer het register (of een deel) en importeer het later.\n• Tweak (op eigen risico): de laatst ingelogde gebruiker niet tonen op het loginscherm.\n– Key: HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\n– Value: dontdisplaylastusername, type DWORD, data 0 = no effect, 1 = niet tonen\n\nOpdracht: back-up maken, de key aanpassen, de back-up importeren en controleren.", o: "Het register", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_regedit_export.jpg",
    uitleg: "In een kantooromgeving is het een nadeel dat alle inlognamen zichtbaar zijn voor een inbreker. Kan ook via group policies." },
  { v: "Wat is het register?", a: "Een centrale, hiërarchische database om het systeem te configureren voor één of meer gebruikers, toepassingen en apparaten.", o: "Het register" },
  { v: "Geef voorbeelden van wat het register bevat.", a: "Profielen per gebruiker, geïnstalleerde toepassingen en welke documenten ze maken, instellingen van eigenschappenvensters en pictogrammen, de hardware en de poorten in gebruik.", o: "Het register" },
  { v: "Welke bestanden vervangt het register?", a: "De tekst-configuratiebestanden van MS-DOS en Windows 3.x, zoals Autoexec.bat en Config.sys.", o: "Het register" },
  { v: "Wat is een registeronderdeel, en waar staan de bestanden?", a: "Een groep sleutels, subsleutels en waarden met ondersteuningsbestanden (back-ups). Behalve HKEY_CURRENT_USER in c:/Windows/System32/config (%SystemRoot%\\System32\\Config).", o: "Het register" },
  { v: "Geef een datatype uit het register.", a: "DWORD (Double-Word).", o: "Het register" },
  { v: "Wanneer gebruik je het register, en waarop let je?", a: "Om virussen volledig te verwijderen of bij hardwareproblemen (bv. een cd-rom die niet herkend wordt). Een verkeerde waarde kan het systeem serieus in de war sturen: maak eerst een back-up.", o: "Het register" },
  { v: "Hoe maak je een back-up van het register?", a: "De registerbestanden kopiëren, of een export maken van het hele register (of een deel) en die later importeren.", o: "Het register" },
  { v: "Open het register.", a: "  Win+R\n  regedit", o: "Het register", oefening: true,
    uitleg: "Win+R = open Run.\nregedit = de Registry Editor (het register)." },
  { v: "Ga in het register naar de locaties van de hives.", a: "regedit → HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\hivelist", o: "Het register", oefening: true },
  { v: "Maak een back-up van je register, pas de tweak aan en zet de back-up terug.", a: "regedit → File → Export (All)\nHKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System → dontdisplaylastusername (DWORD) = 1\nFile → Import → je back-up", o: "Het register", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_regedit_export.jpg",
    uitleg: "Controleer daarna dat de wijziging weg is." },
  { v: "Welke waarde zorgt dat de laatst ingelogde gebruiker niet getoond wordt, en waarom wil je dat?", a: "dontdisplaylastusername (DWORD) op 1. In een kantoor zijn de inlognamen anders bekend bij iemand die wil inbreken.", o: "Het register" },
  { v: "Registry hives", a: "Een hive is een groot hoofddeel van het register, met zijn eigen bestand op de schijf, bv. SYSTEM, SOFTWARE, SAM, SECURITY en per gebruiker NTUSER.DAT. Windows laadt ze bij het opstarten of aanmelden.", o: "Het register", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus." },
  // ===== Systeemvariabelen =====
  { v: "Systeemvariabelen", a: "• Paden en gegevens worden in variabelen bijgehouden; alle programma's kunnen ze gebruiken.\n• Visueel: Verkenner → rechtsklik This PC → Properties → Advanced system settings → Environment Variables.\n• Voor een gebruiker (User variables) of voor het hele systeem (System variables).\n• path: bij het starten van een programma vanuit de prompt (bv. notepad) zoekt CMD de .exe in de mappen van path. Toon de waarde met het commando path.", o: "Systeemvariabelen", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_omgevingsvariabelen.jpg" },
  { v: "path aanpassen en variabelen tonen", a: "• Voorbeeld: PATH=C:\\Windows\\system32;C:\\Windows;C:\\Windows\\System32\\Wbem: Windows zoekt in die 3 mappen.\n• path=\"test\": overschrijft path; de oude waarde ben je kwijt (een nieuwe prompt herstelt ze). Blijvend wijzigen kan met setx (max. 1024 tekens).\n• Path = %path%;c:\\test: voegt c:\\test achteraan toe; ; scheidt de mappen.\n• Een variabele tonen: echo + de naam tussen %, bv. echo %computername%.\n\nOpdracht: zoek met echo de waarde en de uitleg van Appdata, Computername, Localappdata, Path, Pathext, Programfiles en Username.", o: "Systeemvariabelen", wit: true,
    uitleg: "Good to know: ook Errorlevel, Homedrive, Homepath, Os, Processor_architecture, Processor_identifier en Temp." },
  { v: "Good to know: GodMode (niet te kennen)", a: "• GodMode bestaat sinds Windows 7: een snelkoppeling naar een overzicht van alle handige tools om je systeem te beheren.\n• Maak een map (bv. op je bureaublad) met de naam:\nGodMode.{ED7BA470-8E54-465E-825C-99712043E01C}", o: "Systeemvariabelen", extra: true, nietTeKennen: true,
    uitleg: "Good to know: niet te kennen leerstof." },
  { v: "Open de systeemvariabelen visueel.", a: "Verkenner → rechtsklik This PC → Properties → Advanced system settings → Environment Variables", o: "Systeemvariabelen", oefening: true },
  { v: "Voor wie kan je systeemvariabelen aanmaken?", a: "Voor een gebruiker (User variables) of voor het hele systeem (System variables).", o: "Systeemvariabelen" },
  { v: "Waarvoor dient de variabele path?", a: "CMD zoekt een programma dat je start (bv. notepad.exe) in de mappen van path.", o: "Systeemvariabelen" },
  { v: "Toon de huidige waarde van path.", a: "C:\\> path", o: "Systeemvariabelen", oefening: true,
    uitleg: "path = toon de mappen waarin Windows zoekt naar programma's die je typt." },
  { v: "Voeg c:\\test achteraan toe aan path, zonder de oude waarde te verliezen.", a: "C:\\> path=%path%;c:\\test", o: "Systeemvariabelen", oefening: true,
    uitleg: "path= = geef path een nieuwe waarde.\n%path% = de huidige waarde (zo verlies je die niet).\n;c:\\test = ; scheidt de mappen, c:\\test komt erachter." },
  { v: "Wat is het nadeel van path=\"test\", en hoe wijzig je path blijvend?", a: "De vorige waarde ben je kwijt (een nieuwe prompt herstelt ze). Blijvend met setx, maar dat werkt maar met 1024 tekens.", o: "Systeemvariabelen" },
  { v: "Toon de naam van je computer met een variabele.", a: "C:\\> echo %computername%", o: "Systeemvariabelen", oefening: true,
    uitleg: "echo = geef tekst.\n%computername% = de variabele met de naam van je computer. Een variabele tonen: echo + de naam tussen %." },
  { v: "Toon de waarden van Appdata, Localappdata, Path, Pathext, Programfiles en Username.", a: "C:\\> echo %appdata%\nC:\\> echo %localappdata%\nC:\\> echo %path%\nC:\\> echo %pathext%\nC:\\> echo %programfiles%\nC:\\> echo %username%", o: "Systeemvariabelen", oefening: true,
    uitleg: "echo %naam% = toon de waarde van een systeemvariabele: Windows vervangt %naam% door die waarde.\nDe uitleg per variabele staat op de extra kaart 'Uitleg bij de systeemvariabelen'." },
  { v: "Uitleg bij de systeemvariabelen", a: "De cursus vraagt de uitleg zelf op te zoeken:", o: "Systeemvariabelen", extra: true,
    tabel: [
      ["Variabele", "Uitleg"],
      ["Appdata", "de map Roaming van je profiel (AppData\\Roaming)"],
      ["Computername", "de naam van de pc"],
      ["Localappdata", "de map Local van je profiel (AppData\\Local)"],
      ["Path", "de mappen waarin CMD programma's zoekt"],
      ["Pathext", "de extensies die als programma gelden (.COM;.EXE;.BAT;.CMD;...)"],
      ["Programfiles", "de map met geïnstalleerde programma's (C:\\Program Files)"],
      ["Username", "de naam van de ingelogde gebruiker"]
    ] },
  // ===== Taken automatiseren =====
  { v: "Task Scheduler (taakplanner)", a: "• 3 panelen: links de bibliotheek, in het midden de taken, rechts het actievenster.\n• Er staan al taken gepland, bv. MicrosoftEdgeUpdateTaskMachineUA (elke dag).\n• Pc uitschakelen om 16u45: Create Basic Task → naam en beschrijving → dagelijks → programma starten: Shutdown.exe (in c:\\Windows\\System32) met parameter -S (-H sluimerstand, -R herstart, -L afmelden) → voltooien.\n• Probeer ook -S -T 60 -C \"...\": met een boodschap, na 60 seconden.\n• Een Basic Task draait niet als iemand anders ingelogd is: Eigenschappen → Algemeen → uitvoeren ongeacht of de gebruiker is aangemeld.\n• Geschiedenis inschakelen (rechts): dubbelklik op een taak → tabblad Geschiedenis.\n\nOpdracht: laat de Edge-taak enkel lopen als de pc 10 minuten idle is.", o: "Taken automatiseren", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_taakplanner.jpg",
    uitleg: "Extra uit de cursus: maak een taak die de downloadfolder van alle gebruikers elke dag leegmaakt, met een zelfgeschreven .bat-bestand." },
  { v: "Uit welke 3 panelen bestaat de Task Scheduler?", a: "Links de bibliotheek met alle taken, in het midden de taken zelf, rechts het actievenster om ze te beheren.", o: "Taken automatiseren" },
  { v: "Laat de taak MicrosoftEdgeUpdateTaskMachineUA enkel lopen als de pc 10 minuten idle is.", a: "Task Scheduler → de taak → Properties → Conditions → Start the task only if the computer is idle for: 10 minutes", o: "Taken automatiseren", oefening: true },
  { v: "Maak een taak die je pc elke dag om 16u45 uitschakelt.", a: "Create Basic Task → naam en beschrijving → Daily, 16:45 → Start a program\nProgramma: c:\\Windows\\System32\\shutdown.exe, parameter -S → Finish", o: "Taken automatiseren", oefening: true },
  { v: "Wat doen de parameters -S, -H, -R en -L van shutdown?", a: "-S = uitschakelen, -H = sluimerstand, -R = herstarten, -L = afmelden.", o: "Taken automatiseren" },
  { v: "Sluit de pc af binnen 60 seconden, met een waarschuwing.", a: "C:\\> shutdown -S -T 60 -C \"OVER PRECIES ÉÉN MINUUT SLUIT DE PC AF. SLA NU AL JE GEGEVENS OP!\"", o: "Taken automatiseren", oefening: true,
    uitleg: "shutdown = de pc afsluiten.\n-S = shut down (afsluiten).\n-T 60 = na 60 seconden.\n-C \"…\" = de waarschuwing die de gebruiker ziet.\nIn de cursus zijn dit de parameters van de taak. Annuleren: shutdown -A." },
  { v: "Waarom loopt een Basic Task soms niet, en hoe los je dat op?", a: "Niet als iemand anders ingelogd is. Eigenschappen → Algemeen → uitvoeren ongeacht of de gebruiker wel of niet is aangemeld.", o: "Taken automatiseren" },
  { v: "Hoe zie je een gedetailleerde log van een taak?", a: "Rechts de geschiedenis van alle taken inschakelen; dubbelklik op een taak → tabblad Geschiedenis.", o: "Taken automatiseren" },
  // ===== Power Options =====
  { v: "Power Options", a: "• Rechtsklik op de startknop → Power options: wanneer scherm en pc in slaapstand gaan.\n• Handiger: Additional power settings, bv. Hibernate (de)activeren. Hibernate is niet beschikbaar op de VM's, wel op je laptop.\n\nOpdracht: zorg dat de harde schijf nooit deactiveert.", o: "Power Options", wit: true,
    uitleg: "Zoek op wat Hibernate is en wat de voor- en nadelen zijn, als je het niet weet." },
  { v: "Wat stel je in bij Power Options, en waar zitten de handigste zaken?", a: "Wanneer het scherm en de pc in slaapstand gaan. Het handigste zit onder Additional power settings, bv. Hibernate (de)activeren.", o: "Power Options" },
  { v: "Zorg dat de harde schijf nooit deactiveert.", a: "Rechtsklik startknop → Power Options → Additional power settings → Change plan settings → Change advanced power settings → Hard disk → Turn off hard disk after: Never", o: "Power Options", oefening: true },
  { v: "Hibernate", a: "Bij Hibernate (sluimerstand) schrijft Windows het hele werkgeheugen naar de schijf (hiberfil.sys) en schakelt de pc volledig uit. Voordeel: geen stroomverbruik, je werk blijft open. Nadeel: trager opstarten dan slaapstand, en het neemt schijfruimte in.", o: "Power Options", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus." },
  // ===== Event Viewer =====
  { v: "Event Viewer", a: "• Events worden (zo goed als) altijd gelogd; de Event Viewer toont en filtert ze, om software- of hardwareproblemen te vinden.\n• 5 types: Application (geïnstalleerde software), Security (beveiliging), Setup (domain controller), System (Windows-systeemfiles), Forwarded Events (doorgestuurd door een andere computer).\n• Levels: Information (iets veranderd, gestart of beëindigd), Warning (iets kan of begint mis te gaan), Error (iets misgegaan, niet te ernstig), Critical (iets grondig mis, waarschijnlijk gecrasht).\n• Zoek je online, vermeld dan ook de source: elke applicatie kiest haar eigen Event ID's.\n• Event Properties: meer info per event. Filters in het rechterpaneel.\n• Een taak aan een event koppelen: rechtsklik → Attach Task To This Event.\n\nOpdracht: zoek het event van een nieuwe RDP-connectie, maak er een custom filter voor en test met een nieuwe connectie.", o: "Event Viewer", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_attach_task.jpg" },
  { v: "Wat is de Event Viewer?", a: "Een tool om de logs van events in Windows ordelijk te bekijken en te filteren, om te zien of er software- of hardwareproblemen zijn.", o: "Event Viewer" },
  { v: "Geef de 5 types events.", a: "Application, Security, Setup, System en Forwarded Events.", o: "Event Viewer" },
  { v: "Wat bevatten Application, Security, Setup, System en Forwarded Events?", a: "Application: geïnstalleerde software.\nSecurity: de beveiliging.\nSetup: de domain controller (enkel in een domein).\nSystem: de Windows-systeemfiles.\nForwarded Events: doorgestuurd door een andere computer.", o: "Event Viewer" },
  { v: "Geef de 4 levels van een event, van minst tot meest ernstig.", a: "Information, Warning, Error en Critical.", o: "Event Viewer" },
  { v: "Wat betekent elk level?", a: "Information: iets veranderd, gestart of beëindigd.\nWarning: iets kan of begint mis te gaan.\nError: iets misgegaan, niet te ernstig.\nCritical: iets grondig mis, waarschijnlijk gecrasht.", o: "Event Viewer" },
  { v: "Waarom google je niet enkel op het Event ID?", a: "Elke applicatie bepaalt haar eigen Event ID's: vermeld ook de source (of de applicatienaam).", o: "Event Viewer" },
  { v: "Zoek het event van een nieuwe RDP-connectie en maak er een custom filter voor.", a: "Event Viewer → rechterpaneel → Create Custom View → filter op het event\nSluit je RDP-connectie, verbind opnieuw en bekijk of het event erbij staat", o: "Event Viewer", oefening: true,
    uitleg: "Het event toont het IP-adres en de poort van de client." },
  { v: "Koppel een taak aan een event.", a: "Event Viewer → rechtsklik op het event → Attach Task To This Event", o: "Event Viewer", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_attach_task.jpg" },
  // ===== schtasks, arp en netstat =====
  { v: "Extra oefeningen: schtasks, arp en netstat", a: "Niet te kennen, wel om commando's met argumenten en de help te trainen.\n• schtasks: taken uit de Task Scheduler aanmaken via het commando. Bekijk de help en maak een taak.\n• arp: een lijst van de fysieke adressen (MAC) op het netwerk. Bekijk de documentatie en toon de volledige ARP-tabel.\n• netstat: de status van je poorten. Laat ze elke 3 seconden vernieuwen, open een browser en kijk wat verandert; toon alle open poorten.", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true },
  { v: "Bekijk de help van schtasks.", a: "C:\\> schtasks /?", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "schtasks = taken plannen vanuit de CLI.\n/? = toon de help.\nNiet te kennen." },
  { v: "Bekijk de documentatie van arp en toon de volledige ARP-tabel.", a: "C:\\> arp /?\nC:\\> arp -a", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "arp /? = toon de help van arp.\narp -a = toon de volledige ARP-tabel: de bekende koppelingen tussen IP- en MAC-adressen.\nNiet te kennen." },
  { v: "Bekijk met netstat de status van je poorten en vernieuw ze elke 3 seconden.", a: "C:\\> netstat\nC:\\> netstat 3", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "netstat = toon de netwerkverbindingen en poorten.\nnetstat 3 = het getal is het interval: elke 3 seconden opnieuw. Stoppen met Ctrl+C.\nNiet te kennen." },
  { v: "Bekijk de status van alle open poorten.", a: "C:\\> netstat -a", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "netstat = toon de netwerkverbindingen en poorten.\n-a = all: ook de poorten die luisteren.\nNiet te kennen." },
];

